{"cards": [{"node_code": "N_0bc0c3abcb15d0d1", "definition": "研究机场场道排水系统在服役期间的功能监测、排水效率评估、堵塞诊断、维护策略及修复技术的学科分支，确保雨水及地表水及时排除以保障道面结构安全与运行性能。", "boundary": "本节点聚焦于场道排水设施（如边沟、截水沟、渗沟、排水管道）建成后的状态评估与维护。边界在于区分“排水系统维护”与“道面结构维护”，道面裂缝修复归入“场道结构”，新建排水系统设计归入“机场场道排水与防护”。不包含机场航站区或市政区域的排水工程。", "includes": ["场道排水设施的淤积、破损监测与排水能力评价", "排水系统堵塞、渗漏的诊断及清淤、修复技术", "极端降雨条件下场道排水性能评估及应急维护策略"], "excludes": ["新建场道排水系统的设计、选型及施工", "机场非飞行区（如航站区、生活区）的市政排水工程"], "sibling_distinctions": [{"other_code": "N_06ce6f2d04daf3c9", "rule": "本节点关注排水设施的功能与维护，兄弟节点关注道面结构层（面层、基层等）的性能与修复。"}, {"other_code": "N_39fabd0b51968668", "rule": "本节点关注地表水排除系统，兄弟节点关注地基土体的稳定性与沉降监测。"}], "cross_boundary_rule": "当排水失效导致道面结构损坏时，排水设施修复归入本节点，道面结构修复归入“场道结构”；若涉及地基深层排水，需结合地基节点，但主挂载依据主要功能对象确定。"}, {"node_code": "N_abeb6757f79996e4", "definition": "研究机场场址在服役期间的地形地貌变化、地质环境稳定性监测、场址适应性评估及环境维护技术的学科分支，确保机场整体场地条件持续满足运行安全要求。", "boundary": "本节点聚焦于机场宏观场地层面的长期监测与维护，包括地形沉降、边坡稳定、地质灾害风险及场地环境（如植被、水土流失）管理。边界在于区分“场址宏观环境”与“局部工程结构”，局部道面或地基问题归入相应子节点。不包含机场选址规划、征地拆迁或新建场址的地质勘察。", "includes": ["机场场址地形沉降、边坡稳定性及地质灾害风险监测", "场址水土流失、植被恢复及生态环境维护技术", "场址整体适应性评估及长期环境变化对运行安全的影响分析"], "excludes": ["机场新建阶段的选址论证、地质勘察及场地平整", "机场内部具体建筑物、道路或场道的结构维护"], "sibling_distinctions": [{"other_code": "N_39fabd0b51968668", "rule": "本节点关注宏观场址环境稳定性，兄弟节点关注局部地基土体的工程性质与沉降。"}, {"other_code": "N_23663f12ab22a4da", "rule": "本节点关注场址整体环境，兄弟节点关注飞行区具体土建设施（如围界、标志等）的维护。"}], "cross_boundary_rule": "当场址地质变化影响局部地基时，宏观监测归入本节点，局部地基处理归入“地基”；若涉及飞行区具体设施，归入“飞行区土建”。"}, {"node_code": "N_39fabd0b51968668", "definition": "研究机场场道地基在服役期间的沉降监测、承载力评估、土体稳定性诊断、维护策略及加固修复技术的学科分支，确保地基持续满足场道结构承载要求。", "boundary": "本节点聚焦于场道下方地基土体（包括天然地基和处理后地基）的长期性能监测与维护。边界在于区分“地基维护”与“道面结构维护”，道面层问题归入“场道结构”，新建地基处理归入“飞行区土方与地基处理”。不包含机场航站区或市政区域的地基工程。", "includes": ["场道地基沉降、不均匀沉降监测及承载力评估", "地基土体液化、滑移、冻胀等病害诊断与成因分析", "地基加固、注浆、换填等维护修复技术及长期稳定性管理"], "excludes": ["新建场道地基处理、土方工程及基础设计", "机场非飞行区（如航站区、生活区）的地基工程"], "sibling_distinctions": [{"other_code": "N_06ce6f2d04daf3c9", "rule": "本节点关注地基土体性能，兄弟节点关注道面结构层（面层、基层等）性能。"}, {"other_code": "N_abeb6757f79996e4", "rule": "本节点关注局部地基工程性质，兄弟节点关注宏观场址环境稳定性。"}], "cross_boundary_rule": "当地基沉降导致道面损坏时，地基加固归入本节点，道面修复归入“场道结构”；若涉及排水系统导致的地基问题，需结合“排水”节点，但主挂载依据主要病害对象确定。"}]}
